(12, 'Home', 'Home', 'Website Designing and Ecommerce web designing company in  Delhi NCR.', 'Perfect Web Experts is a  IT Company in Delhi, we serves web designing, digital marketing and ecommerce website designing services Delhi, website designing company India.', 'Website Designing Company in Delhi, Website Designing Company in India, Web Designers in Delhi, Web Designers in India, Web Design Company, Web Designing Company, Web Design Company in Delhi, Web Design Company in India, Top website Designing Company in Delhi, Top Website Designing Company in India, Website Designing Services in Delhi, Website Designing Services in India, Delhi web Designing Service, India web Design Service Company, Website Designing Firm in Delhi, Website Designing Companies, Website Designing, Website Designing India, website Designing Delhi, Web Design India, Web Design Delhi, Website Development Company in India, Web Development Company in India, Web Development in India, Web Development in Delhi, Website Provider in Delhi, Company of Web Designing in Delhi, Services of Website Designing in Delhi, web experts, web experts in Delhi, web experts in India, Web Designing Company in Janakpuri, Web Designing Company in Dwarka, Web Designing Company in Vasant Vihar, Seo Services in Janakpuri, Seo Services in Dwarka, Seo Services in Vasant Vihar', NULL, NULL, NULL, NULL, 'header', 'cms page', 'enable', '2020-08-28 00:32:39.000000', '2020-12-03 02:52:13.000000'),
(13, 'About Us', 'About-Us', NULL, NULL, NULL, '1615665808.jpg', '1615663894.jpg', '<p><span style=\"font-size:16px\"><strong><span style=\"font-family:Arial\"><span style=\"color:#000000\">Agnelio &amp; Sons is the best AC&nbsp;sales, repair and maintenance service provider in Goa. They have been in this business for several years and know how to fix the complex electronic application issues. We have a team of experienced and reputed technicians who are readily available to help you resolve or maintain electronic items like refrigerator, AC, microwave, washing machine, or any other home appliances of the customers.&nbsp;Many people in Goa do not pay attention to the health of appliances. Just to save some penny, they avoid repair and maintenance services. If you don&#39;t opt for regular maintenance services, your appliance may get damaged. If you are experiencing some issues with your home appliances, feel free to contact us without thinking much.&nbsp;</span></span></strong></span></p>', '<p><span style=\"font-size:16px\"><strong><span style=\"font-family:Arial\"><span style=\"color:#000000\">Agnelio &amp; Sons is the best electronic items repair and maintenance service provider in Goa. They have been in this business for several years and know how to fix the complex electronic application issues. We have a team of experienced and reputed technicians who are readily available to help you resolve or maintain electronic items like refrigerator, AC, microwave, washing machine, or any other home appliances of the customers.&nbsp;</span></span></strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong><span style=\"font-family:Arial\"><span style=\"color:#000000\">Many people in Goa do not pay attention to the health of appliances. Just to save some penny, they avoid repair and maintenance services. If you don&#39;t opt for regular maintenance services, your appliance may get damaged. If you are experiencing some issues with your home appliances, feel free to contact us without thinking much. At Angelio &amp; Sons, we have been dedicated and committed to providing outstanding and best of our AC repair expertise. Being a reputed and trustworthy AC repair and maintenance service provider, we have set high standards in the market for the type of services we provide to our customers. Our company&#39;s sole purpose is to achieve 100% customers&#39; satisfaction and for that we give our best when it comes to repairing and maintaining a home appliance.&nbsp;</span></span></strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong><span style=\"font-family:Arial\"><span style=\"color:#000000\">Is there any technical glitch in your AC? If yes, then without thinking much feel free to contact us. Angelio &amp; Sons offers you immediate AC repairing and maintenance service in just one call. One of our assistants will come to your doorstep with tools and techniques and fix the issue in no less time. The level of professionalism you will get will take your expectations to the next level. We don&#39;t leave the hands of our customers until they are satisfied with our services. The credibility we have achieved as a leading AC repair and maintenance service provider in Goa is remarkable. At Angelio &amp; Sons, we can do you good with the technical expertise to deal with AC problems.&nbsp;</span></span></strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong><span style=\"font-family:Arial\"><span style=\"color:#000000\">Our aim is to repair and maintain your home appliances and make it work exceptionally. It&#39;s become impossible to use AC in summer without opting for the maintenance services. If you are looking for a reputed and reliable AC repair in Goa, you can contact us anytime. We have a team of highly talented and experienced professionals who will fix all kinds of issues in no less time.&nbsp;</span></span></strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong><span style=\"font-family:Arial\"><span style=\"color:#000000\">Angelio &amp; Sons is the one-stop solution for all kinds of residential and commercial appliances. Whether your commercial AC or residential Washing machine is not working, we can help you out in every possible way. We have passionate and qualified professionals who know how to cater to each user&#39;s demand and offer highly advanced installation, repair, and maintenance of electronic appliances services at cost-effective pricing.&nbsp;</span></span></strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong><span style=\"font-family:Arial\"><span style=\"color:#000000\">Our ultimate goal is to achieve 100% of clients&#39; satisfaction. We are flexible in our approach, if you want someone who can repair your electronic appliance on an immediate note, you can contact us. We offer immediate repair and maintenance services for our prestigious clients.&nbsp;</span></span></strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong><span style=\"font-family:Arial\"><span style=\"color:#000000\">There are many types of electronic appliances used in homes and commercial spaces. And you will be glad after knowing that we have great and extensive knowledge in repairing all kinds of appliances. You can hire for repairing and maintaining AC, microwave, washing machine, and other appliances.&nbsp;</span></span></strong></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><strong><span style=\"font-family:Arial\"><span style=\"color:#000000\">Angelio &amp; Sons are trying to expand its network by offering repair and maintenance service in Goa for residential and commercial spaces. So, if you are looking for a trustworthy and the best AC repair and maintenance service provider in Goa, give a call to Angelio &amp; Sons.&nbsp;</span></span></strong></span></p>\r\n\r\n<p>&nbsp;</p>', 'header and footer', 'cms page', 'enable', '2020-08-28 00:33:34.000000', '2021-03-17 03:08:47.000000'),
(14, 'Contact Us', 'Contact-Us', 'Contact Us : Perfect Web Experts - A Professional Web Designing, Development & SEO Company India', 'Contact Perfect Web Experts, contact web design company, contact web development company, contact seo company, contact digital marketing company, contact web design company India, Contact web designing company in Delhi, Web designing company in Dwarka', 'If you are looking for web designing  and App application development for your complete business solution then Contact Perfect Web Experts - A Professional Web Design,  Development & SEO Company in India. contact web design company, contact web development company, contact seo company, contact digital marketing company, contact web design company India, Contact web designing company in Delhi, Web designing company in Dwarka', '1613983621.jpg', '1609114487.jpg', NULL, NULL, 'header and footer', 'cms page', 'enable', '2020-08-28 00:34:56.000000', '2021-02-22 03:17:01.000000'),
